function SetFilesTotal(t){totalFiles=t}function SetStatusChanged(t){null!=text&&null!=text&&(text.innerHTML=t)}function SetFilesNeeded(t){const e=Math.max(0,Math.min(100,(totalFiles-t)/totalFiles*100));pbar.style.width=`${e}%`}const text=document.querySelector(".status"),pbar=document.querySelector(".progress-bar__count");var totalFiles=1,needed=1;